import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import API from '../api/axiosClient';
import { FaHistory, FaCalendarAlt } from 'react-icons/fa';

export default function CompanyTransactions({ orgId }) {
    const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

    // Fetch transactions filtered by the selected Month and Year
    const { data: transactions = [], isLoading } = useQuery({
        queryKey: ['companyTransactions', orgId, selectedMonth, selectedYear],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/transactions?month=${selectedMonth}&year=${selectedYear}`);
            return res.data;
        }
    });

    return (
        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <h2 className="text-xl font-semibold flex items-center gap-2 text-indigo-400">
                    <FaHistory /> Company Transaction Ledger
                </h2>

                {/* Month and Year Filter Controls */}
                <div className="flex items-center gap-3">
                    <FaCalendarAlt className="text-gray-400" />
                    <select 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="p-2.5 bg-gray-900 border border-gray-700 rounded-lg text-white text-sm"
                    >
                        {Array.from({ length: 12 }, (_, i) => (
                            <option key={i + 1} value={i + 1}>
                                {new Date(0, i).toLocaleString('default', { month: 'long' })}
                            </option>
                        ))}
                    </select>

                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(e.target.value)}
                        className="p-2.5 bg-gray-900 border border-gray-700 rounded-lg text-white text-sm"
                    >
                        <option value="2025">2025</option>
                        <option value="2026">2026</option>
                    </select>
                </div>
            </div>

            {isLoading ? (
                <p className="text-gray-400 text-center py-4">Loading transactions...</p>
            ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b border-gray-700 text-gray-400 text-xs uppercase tracking-wider">
                                <th className="p-3">Customer</th>
                                <th className="p-3">Email</th>
                                <th className="p-3">Type</th>
                                <th className="p-3">Amount</th>
                                <th className="p-3">Machine</th>
                                <th className="p-3">Date</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-700/50">
                            {transactions.length === 0 ? (
                                <tr>
                                    <td colSpan="6" className="p-6 text-center text-gray-500 text-sm">
                                        No transactions recorded for this period.
                                    </td>
                                </tr>
                            ) : (
                                transactions.map((tx) => (
                                    <tr key={tx._id} className="text-sm hover:bg-gray-750 transition">
                                        <td className="p-3 font-medium text-white">{tx.userId?.name || 'Unknown'}</td>
                                        <td className="p-3 text-gray-400">{tx.userId?.email || 'N/A'}</td>
                                        <td className="p-3 text-indigo-300">{tx.type}</td>
                                        <td className="p-3 font-semibold text-emerald-400">${tx.finalPaid?.toFixed(2)}</td>
                                        <td className="p-3 text-gray-400 font-mono text-xs">{tx.machineId}</td>
                                        <td className="p-3 text-gray-400">{new Date(tx.createdAt).toLocaleDateString()}</td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}
